import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, capacity, rev;
        public Edge(int to, int capacity, int rev) {
            this.to = to;
            this.capacity = capacity;
            this.rev = rev;
        }
    }

    static final int MAXN = 210;
    static final int INF = 0x3f3f3f3f;
    static int n, t, start, endNode, edgeCount;
    static int[][] capacity = new int[15][15], science = new int[15][15], mazeStates = new int[65][15][15];
    static int[] head = new int[MAXN], level = new int[MAXN], iter = new int[MAXN];
    static boolean[][] visited = new boolean[15][15], reachable = new boolean[65][15][15][15][15];

    static List<Edge> graph = new ArrayList<>();

    static void add_edge(int u, int v, int cap) {
        graph.add(new Edge(v, cap, graph.size()));
        head[u] = graph.size() - 1;
        graph.add(new Edge(u, 0, graph.size() - 1));
        head[v] = graph.size() - 1;
    }

    static boolean bfs(int s, int t) {
        Arrays.fill(level, -1);
        level[s] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int i = head[u]; i != -1; i = graph.get(i).rev) {
                int v = graph.get(i).to;
                if (graph.get(i).capacity > 0 && level[v] < 0) {
                    level[v] = level[u] + 1;
                    q.offer(v);
                }
            }
        }
        return level[t] >= 0;
    }

    static int dfs(int u, int t, int f) {
        if (u == t) return f;
        for (int i = iter[u]; i != -1; i = graph.get(i).rev) {
            int v = graph.get(i).to;
            if (graph.get(i).capacity > 0 && level[v] == level[u] + 1) {
                int d = dfs(v, t, Math.min(f, graph.get(i).capacity));
                if (d > 0) {
                    graph.get(i).capacity -= d;
                    graph.get(graph.get(i).rev).capacity += d;
                    return d;
                }
            }
        }
        return 0;
    }

    static int max_flow(int s, int t) {
        int flow = 0;
        while (bfs(s, t)) {
            Arrays.fill(iter, 0);
            for (int i = 0; i < MAXN; ++i) iter[i] = head[i];
            int f;
            while ((f = dfs(s, t, INF)) > 0) {
                flow += f;
            }
        }
        return flow;
    }

    static int get_id(int x, int y, int k) {
        return (x - 1) * n + y + k * n * n;
    }

    static void dfs_search(int x, int y, int xx, int yy, int step) {
        visited[xx][yy] = true;
        reachable[step][x][y][xx][yy] = true;
        if (step >= t || mazeStates[step][xx][yy] != 0) return;
        int[][] directions = {{0,1},{0,-1},{1,0},{-1,0}};
        for (int[] dir : directions) {
            int nx = xx + dir[0];
            int ny = yy + dir[1];
            if (nx <= 0 || ny <= 0 || nx > n || ny > n) continue;
            if (visited[nx][ny]) continue;
            if (mazeStates[step][nx][ny] != 0) continue;
            dfs_search(x, y, nx, ny, step + 1);
        }
    }

    static void initialize() {
        for (boolean[] row : visited) {
            Arrays.fill(row, false);
        }
        Arrays.fill(head, -1);
        edgeCount = 0;
        for (int time = 1; time <= t; ++time) {
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    if (mazeStates[time - 1][i][j] != 0)
                        mazeStates[time][i][j] = mazeStates[time - 1][i][j];
                    else {
                        for (int[] k : new int[][]{{0,1},{0,-1},{1,0},{-1,0}}) {
                            int xx = i + k[0];
                            int yy = j + k[1];
                            if (xx <= 0 || yy <= 0 || xx > n || yy > n) continue;
                            if (mazeStates[time - 1][xx][yy] == 2)
                                mazeStates[time][i][j] = 2;
                        }
                    }
                }
            }
        }
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (science[i][j] != 0) {
                    for (boolean[] row : visited) {
                        Arrays.fill(row, false);
                    }
                    dfs_search(i, j, i, j, 0);
                }
            }
        }
        for (int i = 1; i <= t; ++i) {
            for (int x = 1; x <= n; ++x) {
                for (int y = 1; y <= n; ++y) {
                    for (int xx = 1; xx <= n; ++xx) {
                        for (int yy = 1; yy <= n; ++yy) {
                            reachable[i][x][y][xx][yy] |= reachable[i - 1][x][y][xx][yy];
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());
        start = MAXN - 1;
        endNode = start - 1;
        for (int i = 1; i <= n; ++i) {
            String s = br.readLine();
            for (int j = 1; j <= n; ++j) {
                char c = s.charAt(j - 1);
                if (Character.isDigit(c))
                    science[i][j] = c - '0';
                else if (c == 'Y')
                    mazeStates[0][i][j] = 1;
                else if (c == 'Z')
                    mazeStates[0][i][j] = 2;
            }
        }
        for (int i = 1; i <= n; ++i) {
            String s = br.readLine();
            for (int j = 1; j <= n; ++j) {
                char c = s.charAt(j - 1);
                if (Character.isDigit(c))
                    capacity[i][j] = c - '0';
            }
        }
        initialize();
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                if (science[i][j] != 0)
                    add_edge(start, get_id(i, j, 0), science[i][j]);
                if (capacity[i][j] != 0)
                    add_edge(get_id(i, j, 1), endNode, capacity[i][j]);
            }
        }
        for (int x = 1; x <= n; ++x) {
            for (int y = 1; y <= n; ++y) {
                for (int xx = 1; xx <= n; ++xx) {
                    for (int yy = 1; yy <= n; ++yy) {
                        if (science[x][y] != 0 && capacity[xx][yy] != 0 && reachable[t][x][y][xx][yy]) {
                            add_edge(get_id(x, y, 0), get_id(xx, yy, 1), INF);
                        }
                    }
                }
            }
        }
        System.out.println(max_flow(start, endNode));
    }
}
